function uxv2Issues(list) {
  return `<div class="tbl-wrap"><table class="tbl dense ux-tbl"><thead><tr><th scope="col">Severity</th><th scope="col">Area</th><th scope="col">Problem</th><th scope="col">Route</th><th scope="col">Proposed fix</th><th scope="col">Phase</th></tr></thead><tbody>${list.map(i => `<tr><td>${uxSev(i[1])}</td><td class="small nowrap">${UX_CAT[i[2]]}</td><td class="small">${esc(i[3])}</td><td class="small">${esc(i[4])}</td><td class="small">${esc(i[5])}</td><td class="small nowrap">Phase ${i[6]}</td></tr>`).join('')}</tbody></table></div>`;
}
function uxv2Tasks(list) {
  if (!list.length) return '';
  return `<h3>Top tasks</h3><div class="tbl-wrap"><table class="tbl dense ux-tbl"><thead><tr><th scope="col">Task</th><th scope="col">Clicks now</th><th scope="col">Target</th><th scope="col">Meets target?</th><th scope="col">Path today</th></tr></thead><tbody>${list.map(t => `<tr><td class="small strong">${esc(t[1])}</td><td class="small">${esc(t[2])}</td><td class="small nowrap">${esc(t[3])}</td><td>${t[4] === 1 ? chip('Yes', 'green') : t[4] === 2 ? chip('Partly', 'amber') : chip('No', 'red')}</td><td class="small">${esc(t[5])}${t[6] ? `<br><span class="muted">Limit: ${esc(t[6])}</span>` : ''}</td></tr>`).join('')}</tbody></table></div>`;
}
SCREENS['ux-audit-v2'] = () => {
  const fR = ui('uxv2Role', 'every'), fS = ui('uxv2Sev', 'any');
  const keep = i => (fR === 'every' || i[0] === fR) && (fS === 'any' || i[1] === fS);
  const tot = s => UXV2_ISSUES.filter(i => i[1] === s).length;
  const met = UXV2_TASKS.filter(t => t[4] === 1).length, part = UXV2_TASKS.filter(t => t[4] === 2).length;
  const roles = UXV2_ROLES.filter(([k]) => fR === 'every' || k === fR);
  const beh = UXV2_BEHAVIOUR.filter(b => (fR === 'every' || b[0] === fR) && (fS === 'any' || b[1] === fS));
  return `${pageHead('UX Audit v2', 'Phase 1 of the UX polish pass v2. What makes each role view harder to use today, rated by impact on the user, with a route for every issue. Nothing beyond P0 has been changed.')}
  <section class="card"><h2>Summary</h2>
    <div class="ux-kpis"><div><strong>${UXV2_ISSUES.length}</strong><span>issues</span></div><div><strong>${tot('H')}</strong><span>High</span></div><div><strong>${tot('M')}</strong><span>Medium</span></div><div><strong>${tot('L')}</strong><span>Low</span></div><div><strong>${met} of ${UXV2_TASKS.length}</strong><span>top tasks meet target (${part} partly)</span></div><div><strong>${UXV2_BEHAVIOUR.length}</strong><span>behaviour defects (fixed)</span></div></div>
    <p class="small">How this was measured: a code walk-through of every role view on ${UXV2_DATE} (click paths traced from each dashboard; labels, counts, chips, dialogs, empty states, formats and CSS checked), each v1 finding re-checked, and the last full crawl (8 Oct 2026: 908 screens at 390, 1024 and 1440px — no errors, sideways page scroll, dead links or redirects; 423 of 833 role screens contain a table).</p>
    <p class="small">Fixed since v1 (4 Oct): breadcrumbs on the queue item, Learner 360, coordinator and IQA details; ink legends in the Marking Workspace, coordinator submission view and IQA record; Undo says how long you have; resubmission says only the highlighted answers need changes; exports show "Preparing…" then a notification; filters sit behind a Filters toggle on phones; Finance dashboard amounts have pence; placeholder tags no longer sit inside buttons.</p>
    <p class="small">What already works well: the current page is highlighted in every sidebar; skip link and :focus-visible outline in every logged-in shell; reduced motion respected; one page heading per screen; currencies never summed; no other agency's data or IQA content reaches agency screens; verification shows the answer at a glance.</p>
    <p class="small muted">Severity: <strong>High</strong> = blocks or misleads users, or a dead end. <strong>Medium</strong> = slows users down or is inconsistent. <strong>Low</strong> = polish. P0 applied: learner header search removed; voice-to-text confirmed absent.</p>
  </section>
  <section class="card"><div class="ux-filt"><div class="field"><label for="uxv2-r">Role view</label><select class="select" id="uxv2-r" data-onchange="uxF" data-k="uxv2Role"><option value="every">All roles</option>${UXV2_ROLES.map(([k, l]) => `<option value="${k}" ${fR === k ? 'selected' : ''}>${l}</option>`).join('')}</select></div><div class="field"><label for="uxv2-s">Severity</label><select class="select" id="uxv2-s" data-onchange="uxF" data-k="uxv2Sev"><option value="any">Any</option>${Object.entries(UX_SEV).map(([k, v]) => `<option value="${k}" ${fS === k ? 'selected' : ''}>${v[0]}</option>`).join('')}</select></div><p class="small muted" role="status">Showing ${UXV2_ISSUES.filter(keep).length} of ${UXV2_ISSUES.length} issues</p></div></section>
  ${beh.length ? `<section class="card" id="uxv2-beh"><h2>Behaviour defects found — fixed in the Defect fix batch</h2><p class="small">These changed what the prototype does, not how it looks, so they were fixed as a separate "Defect fix" batch before any polish (each restores an agreed rule; see the UX Changelog). Each has a test in the ft-defects suite.</p><div class="tbl-wrap"><table class="tbl dense ux-tbl"><thead><tr><th scope="col">Severity</th><th scope="col">View</th><th scope="col">Defect</th><th scope="col">Route</th><th scope="col">Conflicts with</th></tr></thead><tbody>${beh.map(b => `<tr><td>${uxSev(b[1])}</td><td class="small">${esc((UXV2_ROLES.find(r => r[0] === b[0]) || [, b[0]])[1])}</td><td class="small">${esc(b[2])}</td><td class="small">${esc(b[3])}</td><td class="small">${esc(b[4])}</td></tr>`).join('')}</tbody></table></div></section>` : ''}
  ${roles.map(([k, l]) => { const iss = UXV2_ISSUES.filter(i => i[0] === k && keep(i)), tasks = UXV2_TASKS.filter(t => t[0] === k); if (!iss.length && !(tasks.length && fS === 'any')) return ''; return `<section class="card ux-sec" id="uxv2-${k}"><h2>${l}</h2>${k === 'all' ? '<p class="small muted">These affect every role, so they\'re listed once here rather than repeated under each view.</p>' : ''}${fS === 'any' ? uxv2Tasks(tasks) : ''}${iss.length ? `<h3>Issues (${iss.length})</h3>${uxv2Issues(iss)}` : `<p class="small muted">No ${fS === 'any' ? '' : UX_SEV[fS][0] + ' '}issues beyond the cross-cutting ones.</p>`}</section>`; }).join('')}
  ${fR === 'every' ? `<section class="card"><h2>Newer flows checked</h2><div class="tbl-wrap"><table class="tbl dense ux-tbl"><thead><tr><th scope="col">Flow</th><th scope="col">State</th><th scope="col">Summary</th></tr></thead><tbody>${UXV2_FLOWS.map(f => `<tr><td class="small strong">${esc(f[0])}</td><td>${chip(f[1] === 'red' ? 'Needs work' : 'Usable, gaps', f[1])}</td><td class="small">${esc(f[2])}</td></tr>`).join('')}</tbody></table></div></section>
  <section class="card"><h2>Sidebar size by role</h2><div class="tbl-wrap"><table class="tbl dense"><thead><tr><th scope="col">Role</th><th scope="col" class="r">Sidebar items</th><th scope="col">Grouping</th><th scope="col">Phone bottom bar</th></tr></thead><tbody>${UXV2_NAV.map(r => `<tr><td class="small">${r[0]}</td><td class="r num">${r[1]}</td><td class="small">${r[2]}</td><td class="small">${r[3]}</td></tr>`).join('')}</tbody></table></div><p class="small muted">Counts include the role's screen-index link. The brief suggests a "More" group above about 10 items.</p></section>
  <section class="card"><h2>Still there from v1</h2><ul class="small ux-list">
    <li>${chip('Still there', 'red')} Coordinator header Role → "Teacher" opens "Teacher portal — not yet built".</li>
    <li>${chip('Still there', 'red')} Learner variant E "Viewing as: Teacher (staff)" opens "outside this prototype".</li>
    <li>${chip('Still there', 'red')} The integration banner links non-System roles to a page they can't open.</li>
    <li>${chip('Still there', 'red')} No status-chip tooltips, no table-to-card layout on phones, no skeletons, touch targets under 44px, muted text 4.39:1 on grey, "Sept".</li>
    <li>${chip('Changed', 'amber')} Workplace grant regressed from 3 clicks to 4 + typed name (the typed name is agreed — TBD-156).</li>
    <li>${chip('Changed', 'amber')} Agency assign seats: now 1 + N ticks + 3 with a double confirmation.</li></ul></section>` : ''}
  <section class="card"><h2>What happens next</h2><p class="small">Phase 2 (one design system) starts only after you approve this audit. Each later phase ends with the full regression run and an entry on the UX Changelog page.</p><p class="small"><button class="linklike" data-go="ux-audit">UX Audit v1 (4 Oct)</button> · <button class="linklike" data-go="ux-changelog">UX Changelog</button></p></section>`;
};

const _idxUXV2 = SCREENS.index;
SCREENS.index = p => _idxUXV2(p) + `<section class="card idx-sec"><h2>UX polish pass v2</h2><ul class="idx-list"><li><button class="linklike" data-go="ux-audit-v2">UX Audit v2 (Phase 1)</button> <span class="xs muted">· issues by role with routes, top-task click counts, behaviour defects (fixed)</span></li></ul></section>`;
